            Choice(id="s_ch14_p1_c2", text="[Switch POV to Sherlock Holmes] View Holmes emptying his revolver into the fire-breathing beast.", target_node_id="holmes_ch14_part1_fog_ambush", pov_switch=POV.HOLMES),
